let parsed;
try {
    parsed = JSON.parse(msg.payload);
} catch (e) {
    parsed = { error: "Could not parse JSON body", raw: msg.payload };
}

// Output 1: the HTTP response sent back to the app.
// Access-Control-Allow-Origin is required even without a preflight —
// simple requests still need it on the actual response, or the browser's
// fetch() will reject reading the response even though Node-RED got it fine.
const ack = {
    ...msg,
    statusCode: 200,
    headers: { "Access-Control-Allow-Origin": "*" },
    payload: {
        status: "ok",
        event: parsed.event || null,
        receivedAt: new Date().toISOString()
    }
};

// Output 2: the parsed trip data, for the debug sidebar / further processing.
const debugMsg = { ...msg, payload: parsed };

return [ack, debugMsg];
